```python
def run(self, terms, variables, **kwargs):
    ret = []
    encoding = 'utf-8'
    for term in terms:
        var = term.split()[0]
        value = os.getenv(var)
        if value is not None:
            try:
                ret.append(value.encode(encoding).decode(encoding))
            except UnicodeDecodeError:
                ret.append('')
        else:
            ret.append('')
    return ret
