```python
def run(self, terms, variables, **kwargs):
    ret = []
    for term in terms:
        if isinstance(term, str):
            var = term.split()[0]
            value = os.getenv(var, '')
            if value:
                ret.append(value)
            else:
                # handle the case when environment variable is not set
                ret.append(None)
        else:
            # handle the case when term is not a string
            ret.append(None)
    return ret
```
